/**
 * Environment atlas manifest.
 *
 * `public/assets/tiles.png` is generated by `tools/build-atlas.sh` from the
 * Kenney "Tiny Dungeon" pack (CC0), recoloured into the NULLRUN palette. The
 * order here must match TILES in that script.
 */
export const TILE_SIZE = 16;
export const ATLAS_COLUMNS = 8;

export const TILE_ORDER = [
  'floor_a',
  'floor_b',
  'floor_c',
  'floor_d',
  'wall_a',
  'wall_b',
  'wall_c',
  'door_closed',
  'door_open',
  'cover_a',
  'cover_b',
  'cover_c',
  'core',
  'terminal',
  'vent',
  'extraction',
  'operative',
  'guard_patrol',
  'guard_suspicious',
  'guard_hunting',
  'guard_stunned',
] as const;

export type TileSpriteName = (typeof TILE_ORDER)[number];

export interface AtlasFrame {
  sx: number;
  sy: number;
  sw: number;
  sh: number;
}

export function frameFor(name: TileSpriteName): AtlasFrame {
  const index = TILE_ORDER.indexOf(name);
  const column = index % ATLAS_COLUMNS;
  const row = Math.floor(index / ATLAS_COLUMNS);
  return { sx: column * TILE_SIZE, sy: row * TILE_SIZE, sw: TILE_SIZE, sh: TILE_SIZE };
}

/** Deterministic per-tile variant so the floor doesn't tile visibly. */
export function variantFor(variants: TileSpriteName[], x: number, y: number): TileSpriteName {
  const hash = (x * 73856093) ^ (y * 19349663);
  return variants[Math.abs(hash) % variants.length];
}

export const FLOOR_VARIANTS: TileSpriteName[] = ['floor_a', 'floor_b', 'floor_c', 'floor_d'];
export const WALL_VARIANTS: TileSpriteName[] = ['wall_a', 'wall_b', 'wall_c'];
export const COVER_VARIANTS: TileSpriteName[] = ['cover_a', 'cover_b', 'cover_c'];

export class Atlas {
  private image: HTMLImageElement | null = null;

  get ready(): boolean {
    return this.image !== null && this.image.complete && this.image.naturalWidth > 0;
  }

  async load(src: string): Promise<void> {
    const image = new Image();
    image.src = src;
    await image
      .decode()
      .catch(
        () =>
          new Promise<void>((resolve, reject) => {
            image.onload = () => resolve();
            image.onerror = () => reject(new Error(`failed to load atlas: ${src}`));
          }),
      );
    this.image = image;
  }

  draw(
    ctx: CanvasRenderingContext2D,
    name: TileSpriteName,
    dx: number,
    dy: number,
    size: number,
  ): void {
    if (!this.image) return;
    const frame = frameFor(name);
    ctx.drawImage(this.image, frame.sx, frame.sy, frame.sw, frame.sh, dx, dy, size, size);
  }
}
